 {curves.map((c,i)=>{const color=`var(--learning-${colors[i%3]})`,last=c[c.length-1],prev=c.length>1?c[c.length-2]:last,dx=last&&prev?x(last[0])-x(prev[0]):0,dy=last&&prev?y(last[1])-y(prev[1]):0,norm=Math.hypot(dx,dy),ux=norm?dx/norm:0,uy=norm?dy/norm:0;return <g key={i}>{c.length===1?<circle cx={x(c[0][0])} cy={y(c[0][1])} r="3" fill={color}/>:<path d={c.map(([a,b],j)=>`${j?'L':'M'}${x(a)} ${y(b)}`).join(' ')} fill="none" stroke={color} strokeWidth={i?2:3} strokeDasharray={i?'5 4':undefined}/>} {arrows&&last&&(norm>0?<polygon points={`${x(last[0])},${y(last[1])} ${x(last[0])-8*ux+3*uy},${y(last[1])-8*uy-3*ux} ${x(last[0])-8*ux-3*uy},${y(last[1])-8*uy+3*ux}`} fill={color}/>:<circle cx={x(last[0])} cy={y(last[1])} r="3" fill={color}/>)}</g>;})}
 {dots.map(([a,b],j)=><circle key={j} cx={x(a)} cy={y(b)} r="4" fill={`var(--learning-${dotColors?.[j]??(j?'green':'orange')})`}/>)}
